import{_ as o,o as a,c as t,aw as i}from"./chunks/framework.DLufY-ao.js";const l="/workbook/assets/event-loop-type-tasks.CwLB-oc5.png",h=JSON.parse('{"title":"Виды задач","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/js/event-loop/main/tasks.md","filePath":"wiki/dev-commit/js/event-loop/main/tasks.md"}'),s={name:"wiki/dev-commit/js/event-loop/main/tasks.md"};function c(r,e,n,d,m,k){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="виды-задач" tabindex="-1">Виды задач <a class="header-anchor" href="#виды-задач" aria-label="Permalink to &quot;Виды задач&quot;">​</a></h1><h2 id="задачи" tabindex="-1">Задачи <a class="header-anchor" href="#задачи" aria-label="Permalink to &quot;Задачи&quot;">​</a></h2><h3 id="_1-microtasks" tabindex="-1">1. Microtasks <a class="header-anchor" href="#_1-microtasks" aria-label="Permalink to &quot;1. Microtasks&quot;">​</a></h3><blockquote><p>Очередь микрозадач / задания &quot;jobs&quot; (<em>выполняются все</em>)</p></blockquote><blockquote><p><code>Promises</code>, <code>process.nextTick</code>, <code>Object.observe</code>, <code>Mutation Observer</code></p></blockquote><p>Микрозадачи исполняются по порядку:</p><ul><li>Каждый раз после таски</li><li>Каждый раз когда пустеет стек</li><li>Могут выполняться посередине таска, если очистился стек</li><li>Рекурсивный вызов блокирует Event Loop</li><li><em>Promise.then</em> - микротаск <em>then</em>. <em>Promise.then.then</em> - 2 микротаска</li><li>Сначала выполняется <em>microtasks</em>, затем <em>tasks</em></li></ul><hr><ul><li>Если что-то выполняется, то выполняется 1 раз</li><li>Затем происходит цикл рендеринга</li><li>Если появляется что-то еще, оно планируется</li></ul><h3 id="_2-render-tasks-animation-callbacks" tabindex="-1">2. Render Tasks (Animation Callbacks) <a class="header-anchor" href="#_2-render-tasks-animation-callbacks" aria-label="Permalink to &quot;2. Render Tasks (Animation Callbacks)&quot;">​</a></h3><blockquote><p><code>requestAnimationFrame</code>, <code>Style Recalculate</code>, <code>Layout</code>, <code>Paint</code>, <code>I/O</code>, <code>Рендеринг пользовательского интерфейса</code></p></blockquote><ul><li>Задачи от Render оптимизируются браузером и, если он посчитает, что в этом цикле не нужно ничего перерисовывать, то Event Loop просто пойдет дальше</li></ul><hr><ul><li>Вся запланированная очередь выполняется разом</li><li>Все остальное планируется на следующий раз и добавляется сверху на следующий фрейм</li></ul><h3 id="_3-macrotask-tasks" tabindex="-1">3. Macrotask (Tasks) <a class="header-anchor" href="#_3-macrotask-tasks" aria-label="Permalink to &quot;3. Macrotask (Tasks)&quot;">​</a></h3><blockquote><p>Очередь задач (<em>выполняются по одной</em>)</p></blockquote><blockquote><p><code>setTimeout</code>, <code>setInterval</code>, <code>setImmediate</code>, <code>AJAX</code></p></blockquote><ul><li>Выполняют всё по очереди, даже если есть что-то, что добавлено было сверху</li><li>Браузер может рендерить в промежутках между ними</li><li>Если скорость обработки равна скорости их добавления, то это бесконечный цикл и Event Loop ничего не может сделать, пока не закончатся микротаски</li><li>Поэтому микротаски блокируют рендеринг</li></ul><h2 id="схема" tabindex="-1">Схема <a class="header-anchor" href="#схема" aria-label="Permalink to &quot;Схема&quot;">​</a></h2><img src="'+l+'" width="550px">',20)])])}const p=o(s,[["render",c]]);export{h as __pageData,p as default};
